class ThroneInheritance(private val king:String){
    private val children=mutableMapOf<String,MutableList<String>>();
    private val dead=mutableSetOf<String>();
    fun birth(parentName:String,childName:String){
        children.getOrPut(parentName){
            mutableListOf()
        }.add(childName)
    };
    fun death(name:String){
        dead.add(name)
    };
    private fun dfs(name:String,order:MutableList<String>){
        if(name !in dead)order.add(name);
        for(child in children[name]?:emptyList())dfs(child,order)
    };
    fun getInheritanceOrder():List<String>{
        val order=mutableListOf<String>();
        dfs(king,order);
        return order
    }
}

